window.__posterData({"id": "melwin-rimnas", "name": "Melwin Rimnäs", "folder": "Melwin_Rimnäs_week44-1", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// Rave poster by Melwin with AI added code\n// Process comments are at the bottom.\n\nlet active = false;\nlet img;\nlet colors = [\"#d4d4d8\", \"#b0ff00\", \"#9d00ff\", \"#ff5e00\"];\nlet laserX = [100, 250, 500, 550];\nlet laserSpeed = [5, 8, -5, 8];\n\n// Step 2 addition: simple lingering spray\nlet spray = [];\n\n// Option B: dominant color (null = fully random)\nlet dominantColor = null;\n\nasync function setup() {\n  img = await loadImage('background.jpg');\n  createCanvas(600, 800);\n  textAlign(CENTER, CENTER);\n}\n\nfunction draw() {\n  image(img, 0, 0);\n  noTint();\n\n  if (active === false) showText();\n  if (active) {\n    backgroundTint();\n    showLasers();\n    sprayCanEffect();\n    rotatingText();\n    centralPulse();\n  }\n}\n\nfunction showText() {\n  stroke(0);\n  strokeWeight(4);\n  textSize(38);\n  fill(\"#e4e4e7\");\n  text(\"Rave poster by Melwin\", width / 2, 40);\n  textSize(24);\n  text(\"Mouse 1 to start\", width / 2, 75);\n\n  // Short instructions for keyboard\n  textSize(16);\n  text(\" Key 1-4: set color   5: random\", width / 2, 105);\n}\n\n// Option A: lasers react to mouse speed\nfunction showLasers() {\n  let mouseSpeed = dist(mouseX, mouseY, pmouseX, pmouseY);\n  let thickness = map(mouseSpeed, 0, 40, 5, 16, true);\n  let speedBoost = map(mouseSpeed, 0, 40, 1, 1.8, true);\n\n  for (let i = 0; i < laserX.length; i++) {\n    stroke(dominantColor || colors[i]);\n    // C2: reduced jitter for cleaner beams\n    strokeWeight(thickness + random(-0.5, 0.5));\n    line(mouseX, 5, laserX[i], 800);\n    laserX[i] += laserSpeed[i] * speedBoost;\n    if (laserX[i] <= 0 || laserX[i] >= width) {\n      laserSpeed[i] *= -1;\n    }\n  }\n}\n\n// Step 2 + C1: lingering spray with light gravity\nfunction sprayCanEffect() {\n  for (let n = 0; n < 3; n++) {\n    spray.push({\n      x: mouseX + random(-120, 120),\n      y: mouseY + random(-120, 120),\n      s: random(4, 18),\n      c: dominantColor || random(colors), // Option B: spray also follows selected color\n      a: 255,\n      vy: random(0.2, 0.8)\n    });\n  }\n  for (let i = spray.length - 1; i >= 0; i--) {\n    let p = spray[i];\n    fill(red(p.c), green(p.c), blue(p.c), p.a);\n    noStroke();\n    ellipse(p.x, p.y, p.s);\n    p.y += p.vy;\n    p.vy += 0.04;\n    p.a -= 4;\n    if (p.a <= 0) spray.splice(i, 1);\n  }\n}\n\nfunction rotatingText() {\n  let angle = frameCount * 0.08;\n  push();\n  translate(mouseX, mouseY);\n  rotate(angle);\n  stroke(0);\n  strokeWeight(4);\n  textSize(80);\n  fill(dominantColor || random(colors)); // Option B: spinning text also follows selected color\n  text(\"RAVE\", 0, 0);\n  pop();\n}\n\nfunction backgroundTint() {\n  tint(90, 90);\n  image(img, 0, 0);\n  noTint();\n}\n\n// Pulse sits outside the text and expands outward\nfunction centralPulse() {\n  let base = 240;\n  let outward = sin(frameCount * 0.05) * 22;\n  let s = base + outward;\n\n  noFill();\n  stroke(dominantColor || random(colors));\n  strokeWeight(3);\n  ellipse(mouseX, mouseY, s, s);\n\n  // C3: second thinner ring, also expanding outward\n  strokeWeight(1.5);\n  let s2 = base * 0.82 + sin(frameCount * 0.05 + PI) * 16;\n  ellipse(mouseX, mouseY, s2, s2);\n}\n\n// Option B: keyboard color control\nfunction keyPressed() {\n  if (key === '1') dominantColor = colors[0];\n  if (key === '2') dominantColor = colors[1];\n  if (key === '3') dominantColor = colors[2];\n  if (key === '4') dominantColor = colors[3];\n  if (key === '5' || key === '0') dominantColor = null;\n}\n\nfunction mousePressed() {\n  active = !active;\n  if (!active) spray = [];\n}\n\n/*\nPROCESSKOMMENTARER\n\nJag började med att be AI:n städa koden lite, typ jämnare formatering och push/pop runt den snurrande texten, utan att ändra vad den faktiskt gör. Det blev samma starttext, lasrar och spray, men koden blev mycket lättare att läsa, vilket var skönt att ha som utgångspunkt.\n\nNär det kom till själva effekterna ville jag specifikt att sprayen skulle hänga kvar. Jag hade redan skrivit en kommentar i originalet om att jag försökt lösa det men inte fått till det. AI:n fixade det genom att spara prickarna i en array så att de tonar ut i stället, vilket kändes som en klockren lösning på exakt det jag suttit fast med.\n\nSedan lät jag AI:n föreslå en egen grej utifrån uppgiftsbeskrivningen. Den lade till en pulserande ring, vilket jag tyckte funkade rätt så bra. Den använde samma färger och syntes bara när postern var i gång, så det blev en tydlig fokuspunkt utan att ta över hela bilden.\n\nEfter det testade jag mig fram med lite mindre justeringar. Jag gjorde så att lasrarna blir tjockare och snabbare när man rör musen fort, och flyttade pulsen så att den följer musen. På så sätt hänger lasrarna, texten och pulsen ihop mycket bättre. Jag la basstorleken på 240 så att ringarna hamnar utanför ”RAVE”-texten och expanderar utåt i stället för att täcka bokstäverna. Det var lite klurigt i början och tog några försök att få till storleken utan att det såg konstigt ut.\n\nJag la också in med AI:n så att tangenterna 1–4 styr färgtemat överallt, medan 5 återställer till slumpmässigt. Sprayen fick lite gravitation så prickarna faller nedåt, och jag drog ner jittret på lasrarna och lade till en extra, tunnare ring.\n\nSammanfattningsvis tycker jag att postern behåller känslan från vecka 42, men den är mycket mer responsiv nu. Musen styr det mesta och det är lätt att ändra färg på helheten. Jag tycker verkligen att den färdiga versionen hänger ihop bättre än originalet. Att sprayen faller, pulsen ramar in texten och att färgvalen är flexibla gör att man snabbt kan ändra stämningen utan att det känns som ett helt annat projekt.\n\nAI som användes Grok 4.7\n*/", "assets": {"background.jpg": {"mime": "image/webp", "b64": ""}}});
